import assert from \"node:assert/strict\";
import { spawn } from \"node:child_process\";
import { once } from \"node:events\";
import { test } from \"node:test\";
import { bounded } from \"./synchronization.ts\";

// No listener required: inspect the chosen transport even when connection fails.
// The real CONNECT/model integration remains in network.test.ts.
test(\"startup probe uses HTTPS_PROXY, honors NO_PROXY, and overrides invalid env with host config\", async () => {
  const base = { ...process.env };
  for (const key of [\"HTTP_PROXY\", \"HTTPS_PROXY\", \"http_proxy\", \"https_proxy\", \"NO_PROXY\", \"no_proxy\", \"POLARIS_AGENTD_NETWORK\"]) delete base[key];
  for (const [overrides, expected] of [
    [{ HTTPS_PROXY: \"http://127.0.0.1:1\" }, true],
    [{ HTTPS_PROXY: \"http://127.0.0.1:1\", NO_PROXY: \"127.0.0.1\" }, false],
    [{ HTTP_PROXY: \"invalid-env\", HTTPS_PROXY: \"invalid-env\", http_proxy: \"invalid-env\",
      POLARIS_AGENTD_NETWORK: JSON.stringify({ proxy: \"http://user:probe-secret@127.0.0.1:1\", probeTimeoutMs: 200 }) }, true],
  ] as const) {
    const child = spawn(process.execPath, [\"--import\", \"tsx\", \"src/main.ts\", \"--probe-network\", \"https://127.0.0.1:1/paid\"], {
      env: { ...base, POLARIS_AGENTD_NETWORK: JSON.stringify({ probeTimeoutMs: 200 }), ...overrides },
      stdio: [\"ignore\", \"pipe\", \"pipe\"],
    });
    let stdout = \"\", stderr = \"\";
    child.stdout.on(\"data\", (data) => { stdout += data; });
    child.stderr.on(\"data\", (data) => { stderr += data; });
    try {
      const [code] = await bounded(once(child, \"close\"), \"probe process\");
      assert.equal(code, 0, stderr);
      assert.deepEqual(JSON.parse(stdout), { reachable: false, proxy: expected });
      assert.ok("'!stdout.includes("probe-secret") && !stderr.includes("probe-secret"));
    } finally { if (child.exitCode === null) child.kill("SIGKILL"); }
  }
});
EOF
